-- Migration: extend bookings_pricing_level_check to include the CLIENT level.
--
-- PricingLevel enum grew from (BASE, LOCATION, SLOT, PINCODE) to also include
-- CLIENT, but the old check constraint was generated by Hibernate before that
-- value existed.  We drop the stale constraint and recreate it with the full
-- set so that INSERT / UPDATE with pricing_level = 'CLIENT' no longer fails.
--
-- Run once against any environment whose bookings table still has the old
-- four-value constraint (dev, staging, prod).  The DO block makes it idempotent.

DO $$
DECLARE
    cname TEXT;
BEGIN
    -- Drop every check constraint on the bookings table whose definition
    -- matches the old four-value pattern.  Using a loop handles any
    -- auto-generated name (Hibernate sometimes appends a hash suffix).
    FOR cname IN
        SELECT c.conname
        FROM   pg_constraint c
        JOIN   pg_class      t ON t.oid = c.conrelid
        JOIN   pg_namespace  n ON n.oid = t.relnamespace
        WHERE  t.relname   = 'bookings'
          AND  n.nspname   = current_schema()
          AND  c.contype   = 'c'                    -- CHECK constraint
          AND  pg_get_constraintdef(c.oid) LIKE '%pricing_level%'
    LOOP
        EXECUTE format('ALTER TABLE bookings DROP CONSTRAINT %I', cname);
        RAISE NOTICE 'Dropped stale check constraint: %', cname;
    END LOOP;
END $$;

-- Recreate with the full enum set (must stay in sync with PricingLevel.java).
ALTER TABLE bookings
    ADD CONSTRAINT bookings_pricing_level_check
    CHECK (pricing_level IN ('BASE', 'LOCATION', 'SLOT', 'PINCODE', 'CLIENT'));
